import{_ as p,l as o,o as e,c as s,v as t,p as l,x as r,d as c,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"eBPF 观测","description":"","frontmatter":{"title":"eBPF 观测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ebpf-observability.md","filePath":"cs/ebpf-observability.md","lastUpdated":1789023840000}'),h={name:"cs/ebpf-observability.md"};function f(m,a,B,b,P,_){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ebpf-观测" tabindex="-1">eBPF 观测 <a class="header-anchor" href="#ebpf-观测" aria-label="Permalink to &quot;eBPF 观测&quot;">​</a></h1><div class="epigraph"><p>观测用 BPF 挂在 tracepoint、kprobe、perf 事件上：在核内聚合进 map，用户只读摘要，避免每事件出核。</p><footer>—— 据 Linux bpf(2)；BCC/bpftrace 实践；[XDP](/cs/xdp-ebpf) 为数据面对照</footer></div><p><a href="/cs/perf-sampling">perf</a> 常把样本拷出核。<a href="/cs/ftrace-tracepoints">ftrace</a> 环也会满。缺口是 <strong>eBPF 观测</strong>：在事件处聚合。不是网络过滤重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>程序：读 <code>pt_regs</code>、pid、延迟，<code>map</code> 直方图。verifier 限制。缺口：CO-RE 可移植；与 <a href="/cs/sched-ext">sched_ext</a> 同引擎不同挂钩。本课不把 bpftrace 语法当语言课。</p><p><span class="marginnote">生产观测应优先 tracepoint 再 kprobe。对象是可验证的内核小程序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载 → attach → 事件触发 BPF → 更新 map → 用户轮询 map。对照 XDP：早丢包 vs 记直方图。对照 <a href="/cs/kernel-audit">audit</a>：audit 要合规原文，BPF 常只要统计。对照 ASan：编译插桩 vs 运行时挂接。</p>',8)),(e(),l(d,null,{default:r(()=>[n(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22tracepoint%2Fkprobe%2Fperf%22%5D%20--%3E%20BPF%5B%22eBPF%22%5D%0A%20%20BPF%20--%3E%20MAP%5B%22%E5%93%88%E5%B8%8C%2F%E7%9B%B4%E6%96%B9%E5%9B%BE%20map%22%5D%0A%20%20MAP%20--%3E%20USR%5B%22%E7%94%A8%E6%88%B7%E8%AF%BB%E6%91%98%E8%A6%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>eBPF 把观测从「搬运原始事件」变成「核内折减」，使生产系统可常开。verifier 是安全边界。不要写成 AIOps。与 <a href="/cs/memcg">memcg</a>：map 占内核内存，要限额。</p><p>错误 attach 高频繁点仍可打满 CPU。</p><p>实现上：CO-RE 靠 BTF 把字段偏移从编译时解开。map 大小计入内核内存，要 ulimit/memcg。attach 到高频 kprobe 仍能把 CPU 打满，优先 tracepoint。 读法上只引用<a href="/cs/perf-sampling">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>eBPF 观测</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 helper。不保证稳定 attach 点 ABI——后课 kABI。下一课崩溃转储：kdump。</p><p>版本字段会变，课序钉的是机制对象「eBPF 观测」，不是某一主线内核的结构体名。 后课默认：可在核内用 BPF 聚合事件。崩溃转储 kdump/crash，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>观测 BPF 在事件处聚合到 map。</li><li>比全量出核便宜；挂钩点选择决定税。</li><li>kdump 是下一课。</li><li>出处：bpf(2)；BCC；内核 BPF 文档。</li></ul>',11))])}const E=p(h,[["render",f]]);export{F as __pageData,E as default};
